(function(){
'use strict';

const FLAG='__gamePlanAttackTabs20260814';
if(window[FLAG])return;
window[FLAG]=true;

const ORDER=['z4a','z4b','z2','z3a','z3b'];
const META={z4a:{short:'AR1',role:'Atacante receptora 1'},z4b:{short:'AR2',role:'Atacante receptora 2'},z2:{short:'OP',role:'Opuesta'},z3a:{short:'C1',role:'Central 1'},z3b:{short:'C2',role:'Central 2'}};
const activeByMatch=new Map();
function isCoachEditing(){try{const role=String(typeof getCurrentUser==='function'?(getCurrentUser()?.role||''):'').toLowerCase();const coachRole=['admin','administrator','coach','entrenador'].some(token=>role.includes(token));const coachFn=typeof isCoachUser==='function'&&isCoachUser();const preview=typeof scoutingPreviewMode!=='undefined'&&scoutingPreviewMode;return Boolean((coachFn||coachRole)&&!preview);}catch(_){return false;}}
function matchKey(){try{const id=typeof activeScoutingMatchId!=='undefined'?activeScoutingMatchId:null;return String(id||document.getElementById('scouting-match-select')?.value||'default');}catch(_){return 'default';}}
function mobile(){return window.matchMedia('(max-width:720px)').matches;}
function cardKey(card){const input=card?.querySelector('.attack-name-input');const key=String(input?.id||'').replace('attacker-name-','');return ORDER.includes(key)?key:null;}
function getPlan(){try{return typeof getActiveScoutingPlan==='function'?getActiveScoutingPlan():null;}catch(_){return null;}}
function configured(root,key){if(!root||!key)return false;const live=[...root.querySelectorAll(`input[id^="attacker-${key}-"]`)].some(el=>el.type==='checkbox'&&el.checked);if(live)return true;const dirs=getPlan()?.attackers?.[key]?.directions;return Array.isArray(dirs)&&dirs.length>0;}
function attackSection(root){return root?.querySelector('.attack-module-section')||[...root?.querySelectorAll('.scout-section')||[]].find(section=>section.querySelectorAll('.attack-scout-card').length>=2)||null;}
function cardsFor(section){return [...(section?.querySelectorAll('.attack-scout-card')||[])].map(card=>({card,key:cardKey(card)})).filter(item=>item.key&&ORDER.includes(item.key)).sort((a,b)=>ORDER.indexOf(a.key)-ORDER.indexOf(b.key));}
function setRoleLabels(items){items.forEach(({card,key})=>{const role=card.querySelector('.attack-role');if(role&&META[key])role.textContent=META[key].role;});}
function ensureTabs(section,items){let tabs=section.querySelector('.coach-attack-tabs');if(!tabs){tabs=document.createElement('div');tabs.className='coach-attack-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Seleccionar atacante rival');const head=section.querySelector('.scout-section-head');if(head)head.insertAdjacentElement('afterend',tabs);else section.prepend(tabs);}const known=new Set(items.map(item=>item.key));[...tabs.querySelectorAll('[data-attack-tab]')].forEach(btn=>{if(!known.has(btn.dataset.attackTab))btn.remove();});items.forEach(({key})=>{let btn=tabs.querySelector(`[data-attack-tab="${key}"]`);if(!btn){btn=document.createElement('button');btn.type='button';btn.dataset.attackTab=key;btn.setAttribute('role','tab');btn.setAttribute('aria-label',META[key]?.role||key);btn.innerHTML=`<span>${META[key]?.short||key}</span><b aria-hidden="true">✓</b>`;btn.addEventListener('click',()=>{activeByMatch.set(matchKey(),key);applyActive(section,items,key);});tabs.appendChild(btn);}btn.classList.toggle('is-complete',configured(section,key));});return tabs;}
function applyActive(section,items,requested){const available=items.map(item=>item.key);const active=available.includes(requested)?requested:available[0];if(!active)return;activeByMatch.set(matchKey(),active);const tabs=section.querySelector('.coach-attack-tabs');tabs?.querySelectorAll('[data-attack-tab]').forEach(btn=>{const selected=btn.dataset.attackTab===active;btn.classList.toggle('is-active',selected);btn.setAttribute('aria-selected',selected?'true':'false');btn.tabIndex=selected?0:-1;btn.classList.toggle('is-complete',configured(section,btn.dataset.attackTab));});items.forEach(({card,key})=>{card.dataset.attackTabKey=key;card.dataset.attackTabActive=key===active?'1':'0';});}
function resetDesktop(section,items){section.classList.remove('coach-attack-tabbed-mobile');const host=items[0]?.card?.parentElement;host?.classList.remove('coach-attack-tab-host');items.forEach(({card})=>{card.removeAttribute('data-attack-tab-active');card.removeAttribute('data-attack-tab-key');});}
function decorate(){const root=document.getElementById('scouting-interactive-root');if(!root)return;const section=attackSection(root);if(!section)return;const items=cardsFor(section);if(items.length<2)return;setRoleLabels(items);const tabs=ensureTabs(section,items);const enabled=isCoachEditing()&&mobile();tabs.hidden=!enabled;if(!enabled){resetDesktop(section,items);return;}section.classList.add('coach-attack-tabbed-mobile');const host=items[0]?.card?.parentElement;host?.classList.add('coach-attack-tab-host');const saved=activeByMatch.get(matchKey());applyActive(section,items,saved||items[0].key);}
function bind(){const root=document.getElementById('scouting-interactive-root');if(!root||root.dataset.attackTabsBound==='1')return;root.dataset.attackTabsBound='1';const refresh=()=>requestAnimationFrame(decorate);root.addEventListener('change',event=>{const id=String(event.target?.id||'');if(id.startsWith('attacker-'))refresh();});root.addEventListener('input',event=>{const id=String(event.target?.id||'');if(id.startsWith('attacker-name-'))refresh();});document.getElementById('scouting-match-select')?.addEventListener('change',()=>setTimeout(decorate,0));}
function wrapRender(){if(typeof window.renderTactics!=='function')return false;if(window.renderTactics.__attackTabs20260814)return true;const base=window.renderTactics;const wrapped=function(){const out=base.apply(this,arguments);requestAnimationFrame(()=>{decorate();bind();});return out;};wrapped.__attackTabs20260814=true;window.renderTactics=wrapped;try{renderTactics=wrapped;}catch(_){}return true;}
function injectStyles(){if(document.getElementById('game-plan-attack-tabs-20260814-css'))return;const style=document.createElement('style');style.id='game-plan-attack-tabs-20260814-css';style.textContent=`.coach-attack-tabs{display:none}@media(max-width:720px){#view-tactics .coach-attack-tabs:not([hidden]){display:grid!important;grid-template-columns:repeat(5,minmax(0,1fr));gap:.3rem;width:100%;margin:-.1rem 0 .65rem;padding:.28rem;border:1px solid #dbe2ea;border-radius:13px;background:#eef2f6;box-sizing:border-box}#view-tactics .coach-attack-tabs button{position:relative;display:flex;align-items:center;justify-content:center;gap:.2rem;min-width:0;min-height:40px;padding:.42rem .18rem;border:1px solid transparent;border-radius:9px;background:transparent;color:#64748b;font-size:.72rem;font-weight:900;letter-spacing:.025em;cursor:pointer;box-shadow:none}#view-tactics .coach-attack-tabs button b{display:none;width:14px;height:14px;place-items:center;border-radius:999px;background:#dcfce7;color:#15803d;font-size:.58rem;line-height:1}#view-tactics .coach-attack-tabs button.is-complete b{display:grid}#view-tactics .coach-attack-tabs button.is-active{border-color:#cbd5e1;background:#fff;color:#0f172a;box-shadow:0 2px 7px rgba(15,23,42,.08)}#view-tactics .coach-attack-tabs button.is-active::after{content:'';position:absolute;left:26%;right:26%;bottom:3px;height:2px;border-radius:99px;background:#d97706}#view-tactics .coach-attack-tabbed-mobile .coach-attack-tab-host{display:block!important;width:100%!important;max-width:100%!important;min-width:0!important;overflow:visible!important;padding:0!important;margin:0!important;scroll-snap-type:none!important}#view-tactics .coach-attack-tabbed-mobile .attack-scout-card[data-attack-tab-active="0"]{display:none!important}#view-tactics .coach-attack-tabbed-mobile .attack-scout-card[data-attack-tab-active="1"]{display:block!important;width:100%!important;max-width:100%!important;min-width:0!important;flex:0 0 100%!important;margin:0!important}}`;document.head.appendChild(style);}
function install(){injectStyles();let tries=0;const timer=setInterval(()=>{tries++;const ready=wrapRender();bind();decorate();if(ready&&document.getElementById('scouting-interactive-root'))clearInterval(timer);else if(tries>120)clearInterval(timer);},100);window.matchMedia('(max-width:720px)').addEventListener?.('change',()=>requestAnimationFrame(decorate));}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
})();
